  "claims": [
    {
      "claim": "The query is an aryloxypropanolamine with a tert-butylamino group, matching the core of timolol; timolol's human oral bioavailability is 50-75% in L1 records and 48%/~50% in L2 records, all above the 20% threshold.",
      "card_ids": ["C03","C07","C16","C26","C33","C41"]
    },
    {
      "claim": "Metoprolol, another aryloxypropanolamine beta-blocker, showed systemic availability of 84±10% in cirrhosis; L2 records confirm 78±12% excluding portocaval anastomosis and 84% versus 50% controls.",
      "card_ids": ["C01","C11","C21","C31","C32"]
    },
    {
      "claim": "Propranolol in cirrhosis had L1 F values of 54-79%; L2 records report increased bioavailability in cirrhosis, all above 20%.",
      "card_ids": ["C04","C05","C09","C10","C35","C39"]
    },
    {
      "claim": "Flecainide and encainide contexts report F of 70-95% and 76-78%, with L2 records of ≥95% relative bioavailability and 78±17% in cirrhosis; no context provides affirmative F<20% evidence.",
      "card_ids": ["C02","C13","C19","C25","C29","C12","C15","C22","C34"]
    },
    {
      "claim": "No-condition contexts (safinamide, teriflunomide, perindopril, MMV367, cocaine) report F at or above 20%, with L2 MMV367 records confirming oral bioavailability in preclinical models.",
      "card_ids": ["C08","C06","C20","C18","C24","C14","C23","C27","C37","C38"]
    },
    {
      "claim": "L2 cocaine relative-bioavailability records comparing intranasal and oral routes are not direct absolute-F measurements and do not contradict the high prediction.",
      "card_ids": ["C28","C30"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C29","C31","C32","C33","C34","C35","C36","C39","C40","C41"]
    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C37","C38"]
    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C28","C30"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule; the prediction is transferred from structurally related beta-blocker contexts.",
    "First-pass metabolism and clearance of the query's urea-containing aryloxypropanolamine are not directly measured.",
    "The query has no reported external condition, so cirrhosis or prandial-state contexts are indirect.",
    "L2 records are nonvoting context and do not add independent gold votes.",
    "The physicochemical prior is mixed (low neutral fraction, TPSA 82.6) but is not affirmative evidence for F<20%."
  ],
  "decision_summary": "All visible L1 gold records and the L2 context records from transferable beta-blocker and related contexts report oral bioavailability at or above 20%, mostly 48-100%; the query's tert-butylamino aryloxypropanolamine core aligns with timolol and metoprolol, and no affirmative F<20% evidence is present. Prediction remains high with moderate confidence."
}

